import os, sys
from openpyxl import load_workbook

def find_budget():
    seen = set()
    d = os.path.abspath(os.getcwd())
    for _ in range(6):
        p = os.path.join(d, "budget.xlsx")
        if os.path.isfile(p):
            return p
        up = os.path.dirname(d)
        if up == d:
            break
        d = up
    base = os.path.dirname(os.path.abspath(__file__))
    if base not in seen:
        p = os.path.join(base, "budget.xlsx")
        if os.path.isfile(p):
            return p
    return None

path = find_budget()
if not path:
    sys.exit("ERROR: budget.xlsx not found in workspace")
print("FILE:", path)

wb = load_workbook(path, data_only=True)
grand = 0.0
for ws in wb.worksheets:
    print("\n=== SHEET:", ws.title, "===")
    rows = list(ws.iter_rows(values_only=True))
    if not rows:
        continue
    ncols = max((len(r) for r in rows), default=0)
    # per-column numeric sums and row text tag for first cell
    colsum = [0.0] * ncols
    for r_idx, row in enumerate(rows, start=1):
        first_text = None
        for v in row:
            if isinstance(v, str) and v.strip():
                first_text = v.strip()
                break
        row_numeric = 0.0
        for c_idx, v in enumerate(row):
            if isinstance(v, bool):
                continue
            if isinstance(v, (int, float)):
                row_numeric += float(v)
                if c_idx < ncols:
                    colsum[c_idx] += float(v)
        tag = "" if first_text is None else first_text
        print(f"R{r_idx:02d} [{tag}] numeric_sum={row_numeric} | " + " | ".join("" if v is None else str(v) for v in row))
    print("COLUMN SUMS:", [round(c, 2) for c in colsum])

# Final: sum of the numeric values on the last data/total row's numeric cells is the workbook-designated total if present
print("\nGRAND TOTAL of all numeric cells:", round(grand, 2))

